const shareRow=()=>`<button type="button" class="slink" id="shbt" aria-haspopup="dialog"><span class="sli">${SHARE_IC}</span><span class="slt">Compartilhar o app<small>QR code e link</small></span><i aria-hidden="true">›</i></button>`;
function shareBox(opener){
  showBox('Compartilhar',`<div class="qrbox">${QR_SVG}<span class="note">Aponte a câmera do celular para abrir o app</span></div>
  <div class="lnkbox"><span class="lnk">${SITE.replace('https://','').replace('.io/','.io/<wbr>').replace('27.','27.<wbr>')}</span><button type="button" class="cpy" id="cpy">Copiar link</button></div>${navigator.share?'<button type="button" class="cpy shnat" id="shnat">Enviar por outro app</button>':''}`,opener);
  $('cpy').onclick=()=>{const ok=()=>{$('cpy').textContent='Copiado';toast('Link copiado')};
    try{navigator.clipboard.writeText(SITE).then(ok,()=>toast('Não foi possível copiar'))}catch(e){toast('Não foi possível copiar')}};
  const n=$('shnat');if(n)n.onclick=()=>navigator.share({title:'MedPrumo',text:'Calculadoras, escores, medicamentos e CID-10',url:SITE}).catch(()=>{});
}
let INSTALL_EVT=null;
